/* The fonts in this folder, built in as data, so printed tickets always use the right lettering,
 * even offline or when admin.html is opened straight from a computer. Generated from the .woff2
 * files next to this one; regenerate it if those change. */
window.GT_PRINT_FONTS = "@font-face { font-family: \"Chewy\"; font-weight: 400; src: url(data:font/woff2;base64,) format(\"woff2\"); }\n@font-face { font-family: \"Poppins\"; font-weight: 400; src: url(data:font/woff2;base64,) format(\"woff2\"); }\n@font-face { font-family: \"Poppins\"; font-weight: 600; src: url(data:font/woff2;base64,) format(\"woff2\"); }\n@font-face { font-family: \"Poppins\"; font-weight: 700; src: url(data:font/woff2;base64,) format(\"woff2\"); }\n@font-face { font-family: \"Atkinson Hyperlegible Mono\"; font-weight: 400 600; src: url(data:font/woff2;base64,) format(\"woff2\"); }";
